-- Nonprofits that lost their tax-exempt status -- 1.2M orgs the IRS auto-revoked, keyed by EIN.
-- Auto-generated by scripts/gen_evidence_pages.py: 1,206,628 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
select year("REVOCATION_DATE") as year, count(*) as records
from THE_LIBRARY.COMPANIES.REVOKED_NONPROFITS
where "REVOCATION_DATE" is not null
group by 1
order by 1
